// ═══ importar da Veeqo (S15 Fase 3) ═══════════════════════════════
/* Traz o total da Veeqo pro nosso estoque. A regra que o Bruno travou:
   delta = veeqo.physical − nosso total.
     delta > 0 → entra como "a organizar" (o operador coloca no lugar depois);
     delta < 0 → NUNCA desconta sozinho, volta na lista de revisão manual;
     delta = 0 → pula.
   Por isso o passo 1 mostra a conta antes: quem importa precisa ver quantas
   garrafas vão aparecer do nada no estoque. */
function ImportVeeqoModal({ rows, only, onClose, onDone, onError }) {
  const [busy, setBusy] = React.useState(false);

  const candidates = React.useMemo(() => {
    const list = only ? [only] : rows;
    return list
      .filter((r) => r.base_sku && r.veeqo && r.veeqo.physical != null)
      .map((r) => ({ row: r, delta: n(r.veeqo.physical) - n(r.total) }));
  }, [rows, only]);

  const pos = candidates.filter((c) => c.delta > 0);
  const neg = candidates.filter((c) => c.delta < 0);
  const zero = candidates.filter((c) => c.delta === 0);
  const semSku = (only ? [only] : rows).filter((r) => !r.base_sku || !r.veeqo);
  const totalIn = pos.reduce((a, c) => a + c.delta, 0);

  async function confirm() {
    setBusy(true);
    try {
      const res = await wh.importVeeqo(only ? only.product_id : undefined);
      const d = (res && res.data) || {};
      const nImp = (d.imported || []).length;
      const nNeg = (d.negative || []).length;
      const msg = nImp
        ? nImp + (nImp === 1 ? ' produto importado' : ' produtos importados')
          + (nNeg ? ' · ' + nNeg + ' pra revisar (Veeqo menor que o nosso)' : '')
        : (nNeg ? 'Nada importado · ' + nNeg + ' pra revisar' : 'Nada pra importar, tudo já bate');
      onDone(msg, d);
    } catch (e) {
      onError(e.message || 'erro ao importar');
    } finally { setBusy(false); }
  }

  const listRows = (items, tone) => (
    <div style={{ maxHeight: 190, overflowY: 'auto', marginTop: 6 }}>
      {items.slice(0, 40).map((c) => (
        <div key={c.row.product_id} className="kit-dotted-row" style={{ padding: '6px 0' }}>
          <b style={{ fontSize: 13, flex: 1 }}>{c.row.nickname || c.row.name}</b>
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-dim)' }}>
            {fmt(c.row.total)} → {fmt(n(c.row.veeqo.physical))}
          </span>
          <span className={'kit-chip ' + tone}>{c.delta > 0 ? '+' : ''}{c.delta}</span>
        </div>
      ))}
      {items.length > 40 && (
        <div style={{ fontSize: 12, color: 'var(--ink-faint)', paddingTop: 6 }}>e mais {items.length - 40}</div>
      )}
    </div>
  );

  return (
    <TwoStepModal
      title={only ? 'Importar da Veeqo' : 'Importar da Veeqo (todos)'}
      product={only} baseSku={only ? only.base_sku : null} busy={busy}
      onCancel={onClose} onConfirm={confirm}
      confirmLabel={'Confirmar: importar ' + fmt(totalIn) + ' garrafas'}
      preview={(
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(110px,1fr))', gap: 10 }}>
          <div><div className="kit-mlabel">Entram</div><b>{fmt(pos.length)} produtos</b></div>
          <div><div className="kit-mlabel">Garrafas</div><b>+{fmt(totalIn)}</b></div>
          <div><div className="kit-mlabel">Pra revisar</div><b>{fmt(neg.length)}</b></div>
          <div><div className="kit-mlabel">Já batem</div><b>{fmt(zero.length)}</b></div>
          <div><div className="kit-mlabel">Sem SKU Veeqo</div><b>{fmt(semSku.length)}</b></div>
        </div>
      )}
    >
      {/* Uma frase, primeiro, dizendo o que vai acontecer de verdade. O detalhe
          do caso negativo vem depois, pra quem quiser ler. */}
      <div style={{ fontSize: 14, color: 'var(--ink)', lineHeight: 1.5, fontWeight: 600 }}>
        Vamos usar o número da Veeqo como total e colocar em A organizar. Depois você guarda nas prateleiras e caixas.
      </div>
      <div style={{ fontSize: 13, color: 'var(--ink-dim)', lineHeight: 1.5, marginTop: -4 }}>
        Onde a Veeqo tem MENOS que a gente nada é descontado: essas linhas ficam pra conferir na mão.
      </div>

      {pos.length > 0 && (
        <div>
          <div className="kit-mlabel">Entram no estoque ({pos.length})</div>
          {listRows(pos, 'ok')}
        </div>
      )}

      {neg.length > 0 && (
        <div>
          <div className="kit-mlabel">Veeqo menor que o nosso, revisar à mão ({neg.length})</div>
          {listRows(neg, 'bad')}
        </div>
      )}

      {!pos.length && !neg.length && (
        <div className="kit-card pad" style={{ color: 'var(--ink-dim)' }}>
          Nada pra importar. Ou os totais já batem, ou nenhum produto tem SKU base da Veeqo mapeado.
        </div>
      )}
    </TwoStepModal>
  );
}

/* Painel do drift: a lista dos produtos onde o nosso total e a Veeqo
   discordam. Chega pelo KPI "Δ Veeqo". Nunca sobrescreve nada sozinho, é uma
   lista de conferência com atalho pra importar ou abrir o produto. */
function DriftPanel({ rows, onClose, onOpen, onImport, writable }) {
  const st = wh.useWarehouse('/drift', [], 0);
  // fallback: se o endpoint ainda não responder, calcula do overview
  const fromRows = React.useMemo(() => rows
    .filter((r) => r.veeqo_match === 'drift' && r.veeqo)
    .map((r) => ({ product_id: r.product_id, product: r.nickname || r.name,
                   ours: n(r.total), veeqo: n(r.veeqo.physical), delta: n(r.veeqo.physical) - n(r.total) })),
  [rows]);
  const apiList = (st.data && st.data.drift) || (st.data && st.data.products) || null;
  const list = Array.isArray(apiList) && apiList.length ? apiList : fromRows;

  return (
    <>
      <div className="kit-drawer-back" onClick={onClose} />
      <aside className="kit-drawer" data-panel="drift">
        <div className="head">
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
            <div style={{ flex: 1 }}>
              <div style={{ fontFamily: 'var(--font-display)', fontSize: 26, color: 'var(--primary-deep)', lineHeight: 1.1 }}>
                Diferença com a Veeqo
              </div>
              <div style={{ color: 'var(--ink-dim)', fontSize: 12.5, marginTop: 4 }}>
                {list.length} {list.length === 1 ? 'produto discorda' : 'produtos discordam'}. A Veeqo é comparação, nunca entra na soma sozinha.
              </div>
            </div>
            <button className="kit-btn sec sm" onClick={onClose}>Fechar</button>
          </div>
        </div>
        <div className="body">
          <div className="kit-card pad">
            <table className="kit-table" data-table="drift">
              <thead><tr><th>Produto</th><th className="num">Aqui</th><th className="num">Veeqo</th><th className="num">Δ</th><th /></tr></thead>
              <tbody>
                {list.map((d) => {
                  const row = rows.find((r) => r.product_id === d.product_id);
                  const delta = d.delta != null ? n(d.delta) : n(d.veeqo) - n(d.ours);
                  return (
                    <tr key={d.product_id}>
                      <td><b>{d.product || d.name || (row && (row.nickname || row.name)) || ('#' + d.product_id)}</b></td>
                      <td className="num">{fmt(d.ours != null ? d.ours : (row && row.total))}</td>
                      <td className="num">{fmt(d.veeqo != null ? d.veeqo : (row && row.veeqo && row.veeqo.physical))}</td>
                      <td className="num"><span className="kit-chip bad">{delta > 0 ? '+' : ''}{delta}</span></td>
                      <td>
                        <span style={{ display: 'flex', gap: 5, justifyContent: 'flex-end' }}>
                          {row && <button className="kit-btn xs sec" onClick={() => onOpen(row)}>Ver</button>}
                          {writable && row && delta > 0 && (
                            <button className="kit-btn xs sec" onClick={() => onImport(row)}>Importar</button>
                          )}
                        </span>
                      </td>
                    </tr>
                  );
                })}
                {!list.length && (
                  <tr><td colSpan={5} style={{ color: 'var(--ink-faint)' }}>Nenhuma diferença. Tudo bate com a Veeqo.</td></tr>
                )}
              </tbody>
            </table>
          </div>
          <div style={{ marginTop: 12, lineHeight: 1.6, fontSize: 12.5, color: 'var(--ink-dim)' }}>
            Diferença com sinal de mais: a Veeqo tem mais que a gente, dá pra importar a diferença.
            Com sinal de menos: alguém precisa ir lá contar, o sistema nunca desconta sozinho.
          </div>
        </div>
      </aside>
    </>
  );
}

// ═══ menu de ações da linha ═══════════════════════════════════════
function RowMenu({ row, onAction, writable }) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef(null);
  React.useEffect(() => {
    if (!open) return undefined;
    const off = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', off);
    return () => document.removeEventListener('mousedown', off);
  }, [open]);
  if (!writable) return null;
  // Fase B (Bruno 09-10): os verbos de uma fabrica. Ajustar (delta com sinal) saiu;
  // Contar e "esperado x contado, motivo".
  const items = [
    ['receber', 'Receber'], ['contar', 'Contar'], ['saida', 'Saída'], ['transferir', 'Transferir'],
    ...(n(row.unplaced_qty) > 0 ? [['organizar', 'Organizar']] : []),
    ['mover', 'Mover'], ['separar', 'Separar'],
    ['devolucao', 'Devolução'], ['familia', 'Família/SKUs'],
    ...(row.base_sku ? [['importar-veeqo', 'Importar Veeqo']] : []),
    ['veeqo', 'Veeqo'],
  ];
  return (
    <span ref={ref} style={{ position: 'relative' }} onClick={(e) => e.stopPropagation()}>
      <button className="kit-btn xs sec" data-menu={row.product_id} onClick={() => setOpen((v) => !v)} aria-label="Ações">⋯</button>
      {open && (
        <div className="kit-card" style={{ position: 'absolute', right: 0, top: 30, zIndex: 40, padding: 6, minWidth: 150 }}>
          {items.map(([k, t]) => (
            <button key={k} className="kit-btn xs sec" style={{ width: '100%', justifyContent: 'flex-start', border: 'none', height: 28 }}
                    onClick={() => { setOpen(false); onAction(k, row); }}>{t}</button>
          ))}
        </div>
      )}
    </span>
  );
}

// ═══ página ═══════════════════════════════════════════════════════
export function WarehousePage() {
  const [modal, setModal] = React.useState(null);       // { action, row }
  const [panel, setPanel] = React.useState(null);
  const [importOpen, setImportOpen] = React.useState(null); // null | { only:Row|null }
  const [driftOpen, setDriftOpen] = React.useState(false);
  const [attnAll, setAttnAll] = React.useState(false);      // "ver todos" da caixa de atenção
  const [toast, setToast] = React.useState(null);
  const [rowsPatch, setRowsPatch] = React.useState({}); // product_id → Row atualizado
  const [dropped, setDropped] = React.useState({});     // product_id → sumiu (virou filho)
  const [q, setQ] = React.useState('');
  const [status, setStatus] = React.useState('todos');
  const [area, setArea] = React.useState('todas');
  const [onlyToday, setOnlyToday] = React.useState(false);
  /* Chips rápidos: ligados/desligados por conta própria, e combinar dois é E
     (quem pede "zerado" e "sem local" quer as duas coisas na mesma linha). */
  const [chips, setChips] = React.useState({});
  const [onlyQty, setOnlyQty] = React.useState(false);
  const [expanded, setExpanded] = React.useState({});   // product_id → SKUs abertos
  const [selected, setSelected] = React.useState({});   // product_id → marcado
  const [mergeOpen, setMergeOpen] = React.useState(false);
  const [pageSize, setPageSize] = React.useState(PAGE);

  /* Ordenação da tabela. O padrão continua "disponível ↑" (o que está pra
     acabar primeiro). QUALQUER coluna numérica ordena agora, e a conta é do
     SERVIDOR (sort/dir na query): com ~190 produtos e paginação, ordenar só
     a página baixada mostraria "o maior desta tela", não o maior de todos.
     Primeiro clique numa coluna nova vai DECRESCENTE, que é o "de maior pra
     menor" que o Bruno pediu; só Disponível e Dias começam crescentes,
     porque ali o interessante é quem está acabando. */
  const [sort, setSort] = React.useState({ col: 'available', dir: 'asc' });
  const toggleSort = React.useCallback((col) => {
    setSort((s) => {
      if (s.col === col) return { col, dir: s.dir === 'asc' ? 'desc' : 'asc' };
      return { col, dir: ASC_FIRST.includes(col) ? 'asc' : 'desc' };
    });
  }, []);

  const writable = canWrite();
  /* toast guarda o tom junto com o texto: antes o vermelho dependia da frase
     começar com "erro", então toda mensagem de erro tinha que ser feia.
     `action` = um botão dentro do toast (ex: pular pro Modo completo); com
     botão o toast vive mais, senão some antes do clique. */
  const toastTimer = React.useRef(null);
  const ack = React.useCallback((m, bad, action) => {
    setToast({ msg: m, bad: !!bad, action: action || null });
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), action ? 6500 : 2600);
  }, []);
  const ackErr = React.useCallback((e) => { ack(friendlyError(e), true); }, [ack]);

  /* ── MODO SIMPLES × MODO COMPLETO ────────────────────────────────
     O padrão do hub é o modo do MUTIRÃO (Bruno 09-04): uma linha por
     produto com o número da Veeqo do lado da contagem real, tudo editável
     ali. O Modo completo (KPIs, filtros, painel, modais) continua inteiro
     atrás do botão. A escolha segue a conta, como a vista. */
  const [mode, setMode] = useAccountPref('estoque.modo', 'simples', { localKey: 'hf-estoque-modo' });
  const simple = mode !== 'completo';
  const [weigh, setWeigh] = React.useState(null);      // Row do popover de pesagem

  /* ── VISTA SALVA NA CONTA ────────────────────────────────────────
     Busca, chips, ordem e "só com quantidade" seguem a PESSOA, não o
     navegador: quem arruma a tela do jeito dele reencontra igual no PC do
     armazém (prefs 'estoque.view', a mesma porta da página Hoje).
     A vista é aplicada UMA vez, quando a conta responde: reaplicar a cada
     render tiraria a tela da mão de quem está mexendo nela agora. */
  const [view, setView, viewMeta] = useAccountPref('estoque.view', null, { localKey: 'hf-estoque-view' });
  const viewApplied = React.useRef(false);
  React.useEffect(() => {
    if (viewApplied.current || !viewMeta.loaded) return;
    viewApplied.current = true;
    if (!view || typeof view !== 'object') return;
    if (typeof view.q === 'string') setQ(view.q);
    if (view.chips && typeof view.chips === 'object') setChips(view.chips);
    if (typeof view.onlyQty === 'boolean') setOnlyQty(view.onlyQty);
    if (view.sort && view.sort.col) setSort({ col: view.sort.col, dir: view.sort.dir === 'desc' ? 'desc' : 'asc' });
  }, [view, viewMeta.loaded]);

  const currentView = React.useMemo(
    () => ({ q, chips, onlyQty, sort }),
    [q, chips, onlyQty, sort],
  );
  /* "Tem coisa pra salvar?" = o que está na tela difere do que está na conta.
     Sem isso o botão Salvar ficaria aceso pra sempre, e um botão sempre aceso
     não avisa nada. */
  const viewDirty = React.useMemo(() => {
    const a = JSON.stringify(currentView);
    const b = JSON.stringify(view || { q: '', chips: {}, onlyQty: false, sort: { col: 'available', dir: 'asc' } });
    return a !== b;
  }, [currentView, view]);

  /* ── A BUSCA, NO SERVIDOR ────────────────────────────────────────
     q, ordem, chips e paginação viram query string. O servidor devolve
     { products, total, kpis, attention, pending_summary }: `total` é quantos
     produtos passam no filtro (o M do "N de M") e products é a página. */
  const chipStatuses = React.useMemo(
    () => QUICK_FILTERS.filter((f) => chips[f.k]).map((f) => f.value),
    [chips],
  );
  const statusParam = React.useMemo(() => {
    const all = [...chipStatuses];
    if (status !== 'todos' && !all.includes(status)) all.push(status);
    return all.join(',');
  }, [chipStatuses, status]);

  /* Modo simples: SEM filtros de status e SEM paginação curta. O mutirão
     percorre o catálogo inteiro em ordem de nome (a ordem da prateleira na
     cabeça de quem conta); só a busca recorta. */
  const path = React.useMemo(() => wh.overviewQuery(simple
    ? { q: q.trim(), sort: 'name', dir: 'asc', limit: 500, offset: 0 }
    : {
      q: q.trim(), sort: sort.col, dir: sort.dir,
      status: statusParam, only_with_qty: onlyQty,
      limit: pageSize, offset: 0,
    }), [simple, q, sort, statusParam, onlyQty, pageSize]);

  // poll 20s, PAUSADO enquanto um modal está aberto (inclusive o de import
  // e o popover da balança: trocar a linha embaixo de quem digita é sabotagem)
  const ov = wh.useWarehouse(path, [], 20000, !!modal || !!importOpen || !!mergeOpen || !!weigh);
  const data = ov.data || {};
  const kpis = data.kpis || {};

  /* Pesos por produto (pro popover da balança): uma busca só, no modo
     simples. Se falhar, o popover cai no caminho de calibrar: nunca trava. */
  const ws = wh.useWarehouse(simple ? '/weights' : null, [], 0);
  const weightOf = React.useCallback((productId) => {
    const list = (ws.data && ws.data.products) || [];
    return list.find((x) => x.product_id === productId) || null;
  }, [ws.data]);

  /* Uma linha por PRODUTO: as que viraram filhas somem na hora, sem esperar o
     poll. Foi a pessoa que mandou juntar, ver a linha antiga ainda ali por 20
     segundos faz parecer que não funcionou. */
  const rawRows = React.useMemo(
    () => (data.products || []).filter((r) => !dropped[r.product_id]),
    [data.products, dropped],
  );
  const rows = React.useMemo(
    () => rawRows.map((r) => rowsPatch[r.product_id] || r),
    [rawRows, rowsPatch],
  );

  const onRowUpdate = React.useCallback((product) => {
    if (product && product.product_id != null) setRowsPatch((p) => ({ ...p, [product.product_id]: product }));
  }, []);

  // opções dos filtros
  const statuses = React.useMemo(() => {
    const s = new Set();
    rows.forEach((r) => (r.status || []).forEach((x) => s.add(x)));
    return [...s].sort();
  }, [rows]);
  const areas = React.useMemo(() => {
    const s = new Set();
    rows.forEach((r) => {
      (r.bins || []).forEach((b) => b.area && s.add(b.area));
      (r.boxes || []).forEach((b) => b.area && s.add(b.area));
    });
    return [...s].sort();
  }, [rows]);

  /* ── A MESMA REGRA, DE NOVO, NO NAVEGADOR ────────────────────────
     Isto é REDE DE SEGURANÇA, não a fonte. O servidor já filtrou e ordenou;
     mas um backend que ainda não conhece `sort` devolve a lista crua, e aí
     clicar no cabeçalho não faria nada na tela. Reaplicar aqui custa nada
     sobre uma página de 60 linhas e garante que o que a pessoa clica sempre
     acontece. Quando os dois concordam, este passo é idempotente. */
  const VAL = {
    total: (r) => n(r.total), shelf: (r) => n(r.shelf_qty), box: (r) => n(r.box_qty),
    unplaced: (r) => n(r.unplaced_qty), reserved: (r) => n(r.reserved),
    pending: (r) => n(r.pending_in) - n(r.pending_out),
    available: (r) => n(r.available), separated: (r) => n(r.separated),
    days: (r) => (r.days_of_stock == null ? null : Number(r.days_of_stock)),
    veeqo: (r) => (r.veeqo && r.veeqo.physical != null ? n(r.veeqo.physical) : null),
    name: (r) => String(r.nickname || r.name || '').toLowerCase(),
  };

  const filtered = React.useMemo(() => {
    const needle = q.trim().toLowerCase();
    const wanted = chipStatuses;
    let out = rows.filter((r) => {
      if (needle) {
        const hay = [r.nickname, r.name, r.base_sku, r.barcode,
          ...(r.skus || []).map((s) => s.sku),
          ...(r.children || []).map((s) => s.sku)].filter(Boolean).join(' ').toLowerCase();
        if (!hay.includes(needle)) return false;
      }
      // chips somam: pedir "zerado" e "sem local" é pedir as duas coisas
      if (wanted.length && !wanted.every((w) => (r.status || []).includes(w))) return false;
      if (status !== 'todos' && !(r.status || []).includes(status)) return false;
      if (area !== 'todas') {
        const has = (r.bins || []).some((b) => b.area === area) || (r.boxes || []).some((b) => b.area === area);
        if (!has) return false;
      }
      if (onlyQty && !n(r.total)) return false;
      if (onlyToday && !n(r.reserved)) return false;
      return true;
    });
    /* Vazio vai SEMPRE pro fim, nos dois sentidos: "não vendeu nada" e "sem
       SKU na Veeqo" não são urgentes nem folgados, são ausência de
       informação, e misturar isso com o que está pra acabar esconde a linha
       que importa. Empate cai no nome, pra ordem não dançar entre polls. */
    const get = VAL[sort.col] || VAL.available;
    const mul = sort.dir === 'asc' ? 1 : -1;
    out = out.slice().sort((a, b) => {
      const va = get(a); const vb = get(b);
      if (va == null && vb == null) return VAL.name(a) < VAL.name(b) ? -1 : 1;
      if (va == null) return 1;
      if (vb == null) return -1;
      if (va === vb) return VAL.name(a) < VAL.name(b) ? -1 : 1;
      return (typeof va === 'string' ? (va < vb ? -1 : 1) : va - vb) * mul;
    });
    return out;
  // VAL é constante entre renders (literal sem dependência de estado)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows, q, chipStatuses, status, area, onlyQty, onlyToday, sort]);

  /* "N de M": M vem do servidor quando ele conta (contrato P2); sem isso,
     o que a página tem na mão é o melhor número honesto que existe. */
  const totalCount = Number.isFinite(Number(data.total)) ? Number(data.total) : rows.length;
  const hasMore = filtered.length < totalCount && rows.length >= pageSize;

  /* Aviso de propostas paradas. pending_summary vem do overview (contrato 3);
     se o backend ainda não mandar, cai no KPI que a página já recebia, pra
     tela não ficar muda no meio do deploy. */
  const pendingSummary = data.pending_summary || null;
  const pendingCount = pendingSummary && Number.isFinite(Number(pendingSummary.count))
    ? Number(pendingSummary.count)
    : n(kpis.pending_requests);
  const pendingAge = pendingSummary ? fmtAge(pendingSummary.oldest_age_min) : null;

  const empty = !ov.loading && rows.length > 0 && rows.every(
    (r) => !(r.bins || []).length && !(r.boxes || []).length && !n(r.total),
  );

  function openAction(action, row) {
    if (action === 'familia') { setPanel(row); return; }
    if (action === 'veeqo') { window.location.hash = '#estoque-geral'; return; }
    if (action === 'importar-veeqo') { setImportOpen({ only: row }); return; }
    setModal({ action, row });
  }

  async function approve(requestId) {
    try { const r = await wh.approveRequest(requestId); ack('Aprovado. O número do produto já mudou.'); if (r && r.data && r.data.product) onRowUpdate(r.data.product); ov.refresh(); }
    catch (e) { ackErr(e); }
  }

  /* ── EDIÇÃO NA CÉLULA ────────────────────────────────────────────
     "Um clique, digita, pronto." O que a célula faz por baixo:

       Prateleira / Caixa / A organizar → POST /product/:id/adjust com o
       DELTA e o local. Nunca um PUT de quantidade: adjust é a porta que já
       existe, passa pelo StockService e deixa o movimento registrado com
       quem fez e por quê. A tela nunca escreve número no banco.

     OTIMISTA COM VOLTA ATRÁS: o número novo entra no rowsPatch na hora. Se
     a API recusar, o patch é DESFEITO (a linha volta ao que o servidor
     mandou) e o toast diz o porquê. Nunca fica um número na tela que o
     banco não tem.

     Prateleira e Caixa só são editáveis com UM local: com duas prateleiras
     "prateleira = 40" não diz em qual, e adivinhar mexeria no lugar errado.
     Nesses casos a célula fica só de leitura e a linha manda usar Mover. */
  const inlineEdit = React.useCallback(async ({ row, field, delta, reason }) => {
    const before = rowsPatch[row.product_id];
    const optimistic = { ...row };
    if (field === 'shelf') optimistic.shelf_qty = n(row.shelf_qty) + delta;
    else if (field === 'box') optimistic.box_qty = n(row.box_qty) + delta;
    else optimistic.unplaced_qty = n(row.unplaced_qty) + delta;
    optimistic.total = n(row.total) + delta;
    optimistic.available = n(row.available) + delta;
    setRowsPatch((p) => ({ ...p, [row.product_id]: optimistic }));

    const body = { qty: delta, reason: reason || 'ajuste na tabela do estoque' };
    if (field === 'shelf' && (row.bins || []).length === 1) body.bin_id = row.bins[0].id;
    if (field === 'box' && (row.boxes || []).length === 1) body.box_id = row.boxes[0].id;

    try {
      const res = await wh.postAdjust(row.product_id, body);
      if (res && res.data && res.data.product) onRowUpdate(res.data.product);
      ack('Salvo. ' + (delta > 0 ? '+' : '') + delta + ' em ' + (
        field === 'shelf' ? 'Prateleira' : field === 'box' ? 'Caixa' : 'A organizar') + '.');
    } catch (e) {
      // volta pro que o servidor mandou: o patch otimista some
      setRowsPatch((p) => {
        const next = { ...p };
        if (before) next[row.product_id] = before; else delete next[row.product_id];
        return next;
      });
      ackErr(e);
      throw e;   // a célula fecha sabendo que não salvou
    }
  }, [rowsPatch, onRowUpdate, ack, ackErr]);

  /* ── A CÉLULA DO MUTIRÃO (modo simples) ──────────────────────────
     Manda o ABSOLUTO que a pessoa contou pro POST /simple/set; o backend
     calcula o delta e aplica só verbos do StockService. A linha atualiza da
     RESPOSTA (o chip de conferência vira na hora), nunca de palpite local.
     Produto com mais de um local → 409 multi_location: o simples não
     adivinha em qual prateleira, o toast leva pro Modo completo. */
  const simpleCommit = React.useCallback(async ({ row, scope, qty, bin_code }) => {
    const body = { product_id: row.product_id, scope, qty, client_ref: newRef() };
    if (bin_code) body.bin_code = bin_code;
    try {
      // guarda de tamanho (Fase A): acima do alvo da Veeqo o backend devolve
      // over_target e a pessoa confirma com os dois numeros na frente
      let res;
      try { res = await wh.simpleSet(body); }
      catch (e1) {
        if (e1 && e1.code === 'over_target' && window.confirm(e1.message)) res = await wh.simpleSet({ ...body, confirm: true });
        else throw e1;
      }
      const d = (res && res.data) || {};
      const patched = {
        ...row,
        shelf_qty: d.shelf_qty, box_qty: d.box_qty, unplaced_qty: d.unplaced_qty,
        total: d.total, veeqo_total: d.veeqo_total,
        home_bin: d.home_bin || row.home_bin || null,
        main_box: d.main_box || row.main_box || null,
      };
      if (d.home_bin && !(row.bins || []).some((b) => b.id === d.home_bin.id)) {
        patched.bins = [...(row.bins || []), { id: d.home_bin.id, bin_code: d.home_bin.bin_code, qty: d.shelf_qty }];
      }
      if (d.main_box && !(row.boxes || []).some((b) => b.id === d.main_box.id)) {
        patched.boxes = [...(row.boxes || []), { id: d.main_box.id, box_number: d.main_box.box_number, qty: d.box_qty }];
      }
      onRowUpdate(patched);
      const hadBox = !!(row.main_box || (row.boxes || []).length);
      const hadBin = !!(row.home_bin || (row.bins || []).length);
      if (scope === 'box' && d.main_box && !hadBox) {
        ack('Salvo na caixa ' + d.main_box.box_number + ' (criada agora).');
      } else if (scope === 'shelf' && d.home_bin && !hadBin) {
        ack('Prateleira ' + d.home_bin.bin_code + ' criada com a contagem.');
      } else {
        ack(d.match ? 'Salvo. Bate com a Veeqo.' : 'Salvo.');
      }
    } catch (e) {
      if (e && (e.code === 'multi_location' || e.status === 409)) {
        ack('Esse produto tem mais de um local. Ajuste no Modo completo.', true,
          { label: 'Modo completo', run: () => setMode('completo') });
        throw e;
      }
      ackErr(e);
      throw e;
    }
  }, [onRowUpdate, ack, ackErr, setMode]);

  /* Sugestão do próximo código de prateleira (padrão A01A1), calculada dos
     códigos que já existem na página. Texto puro: a pessoa pode trocar. */
  const suggestedCode = React.useMemo(() => suggestBinCode(rows), [rows]);

  /* Imprimir a linha: as etiquetas da prateleira e da caixa DESTE produto,
     na página de etiquetas que já existe (mesmo desenho Code 128 + QR do
     resto do sistema; nada é redesenhado aqui). */
  const printRow = React.useCallback((row) => {
    const hb = homeBinOf(row);
    const mb = mainBoxOf(row);
    const parts = [];
    if (hb) parts.push('bins=' + hb.id);
    if (mb) parts.push('boxes=' + mb.id);
    if (!parts.length) return;
    window.location.hash = '#estoque-etiquetas?' + parts.join('&');
  }, []);

  /* Apelido: texto puro, não mexe em estoque nenhum. Vai pela MESMA porta do
     Product Setup (POST /product-setup/:id), que é quem já é dona do campo:
     duas telas gravando o apelido por caminhos diferentes é como se cria um
     apelido que só existe numa delas. */
  const inlineNickname = React.useCallback(async (row, value) => {
    const before = rowsPatch[row.product_id];
    setRowsPatch((p) => ({ ...p, [row.product_id]: { ...row, nickname: value } }));
    try {
      await apiPost('/product-setup/' + row.product_id, { nickname: value });
      ack('Apelido salvo.');
    } catch (e) {
      setRowsPatch((p) => {
        const next = { ...p };
        if (before) next[row.product_id] = before; else delete next[row.product_id];
        return next;
      });
      ackErr(e);
      throw e;
    }
  }, [rowsPatch, ack, ackErr]);

  /* ── JUNTAR / DESAGRUPAR ─────────────────────────────────────────
     Juntar tira linhas da tabela; desagrupar devolve uma. Nos dois casos a
     tela reage NA HORA (dropped / refresh) porque foi a pessoa que mandou:
     esperar o poll de 20s faria parecer que o clique não pegou. */
  const onMergeDone = React.useCallback((msg, _label, goneIds) => {
    // as linhas que viraram filhas somem AGORA, sem esperar os 20s do poll
    if (Array.isArray(goneIds) && goneIds.length) {
      setDropped((d) => {
        const next = { ...d };
        goneIds.forEach((id) => { next[id] = true; });
        return next;
      });
    }
    setSelected({});
    setMergeOpen(false);
    ack(msg);
    ov.refresh();
  }, [ack, ov]);

  const onUnmerge = React.useCallback(async (child) => {
    try {
      await wh.unmergeFamily(child.product_id);
      // ela volta a existir: se estava escondida por um merge anterior, reaparece
      setDropped((d) => { const nx = { ...d }; delete nx[child.product_id]; return nx; });
      ack(child.sku + ' voltou a ter linha própria no estoque.');
      ov.refresh();
    } catch (e) { ackErr(e); }
  }, [ack, ackErr, ov]);

  const selectedIds = React.useMemo(
    () => Object.keys(selected).filter((k) => selected[k]).map(Number),
    [selected],
  );

  if (!canRead()) {
    return (
      <div style={{ padding: 40, textAlign: 'center', color: 'var(--ink-dim)' }}>
        <h2 className="kit-h2">Sem acesso ao estoque</h2>
        <p className="kit-sub">Essa página precisa da função view_stock. Fale com o Admin.</p>
      </div>
    );
  }

  /* Mesmas palavras da tabela e do hub do operador (Total · Reservado ·
     Disponível · Separadas · A organizar). "Δ Veeqo" virou "Veeqo diferente":
     ninguém no armazém lê delta. */
  const KPIS = [
    { k: 'todos',      label: 'Total',            value: kpis.total_bottles },
    { k: 'reservadas', label: 'Reservado',        value: kpis.reserved },
    { k: 'dispon',     label: 'Disponível',       value: kpis.available },
    { k: 'separadas',  label: 'Separadas',        value: kpis.separated },
    { k: 'organizar',  label: 'A organizar',      value: kpis.unplaced,        tone: n(kpis.unplaced) ? 'warn' : '' },
    { k: 'repor',      label: 'Prateleiras a repor', value: kpis.bins_to_restock, tone: n(kpis.bins_to_restock) ? 'warn' : '' },
    { k: 'pendente',   label: 'Aprovações',       value: kpis.pending_requests, tone: n(kpis.pending_requests) ? 'warn' : '' },
    { k: 'drift',      label: 'Veeqo diferente',  value: kpis.drift_products,   tone: n(kpis.drift_products) ? 'bad' : '' },
  ];

  return (
    <div className="wh-root" data-page="estoque" style={{ paddingBottom: 60 }}>
      {/* header */}
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 16, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 280 }}>
          <span className="kit-eyebrow">● HEALTHFARE P&amp;P · ESTOQUE</span>
          <h1 className="kit-h1">Estoque do <em>armazém</em></h1>
          <p className="kit-sub">
            Total = prateleira + caixa + a organizar. Reservado vem dos pedidos abertos da Veeqo. Separadas nunca contam.
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {/* o hub abre no modo do mutirão; a tabela completa fica a 1 clique */}
          <button className="kit-btn sec" data-act="modo-view"
                  title={simple ? 'Abrir a tabela completa (KPIs, filtros, painéis)' : 'Voltar pra tela simples da contagem'}
                  onClick={() => setMode(simple ? 'completo' : 'simples')}>
            {simple ? 'Modo completo' : 'Modo simples'}
          </button>
          {writable && (
            <button className="kit-btn primary" data-act="entrada-top"
                    onClick={() => filtered[0] && openAction('receber', filtered[0])}>Receber</button>
          )}
          {writable && (
            <button className="kit-btn sec" data-act="juntar-skus"
                    title="Casepack é a mesma garrafa: junta as linhas repetidas numa só"
                    onClick={() => setMergeOpen(true)}>Juntar SKUs</button>
          )}
          {writable && (
            <button className="kit-btn sec" data-act="importar-veeqo"
                    onClick={() => setImportOpen({ only: null })}>Importar da Veeqo</button>
          )}
          <a className="kit-btn sec" href="#estoque-aprovacoes">Aprovações ({fmt(kpis.pending_requests)})</a>
          <a className="kit-btn sec" href="#estoque-locais">Locais</a>
          <a className="kit-btn sec" href="#estoque-etiquetas">Etiquetas</a>
        </div>
      </div>

      {/* KPIs (clicáveis → filtram) — só no Modo completo */}
      {!simple && (
      <div style={{ display: 'flex', gap: 10, marginTop: 18, flexWrap: 'wrap' }} data-kpis>
        {KPIS.map((kp) => (
          <button key={kp.k} type="button"
                  className={'kit-kpi-card ' + (status === kp.k ? 'on' : '')}
                  data-kpi={kp.k}
                  onClick={() => {
                    if (kp.k === 'todos') { setStatus('todos'); setChips({}); return; }
                    if (kp.k === 'pendente') { setChips({ pend: true }); setStatus('todos'); return; }
                    // Δ Veeqo abre a LISTA da diferença: filtrar a tabela não
                    // responde "quanto e pra que lado", que é o que se quer aqui.
                    if (kp.k === 'drift') { setDriftOpen(true); return; }
                    if (statuses.includes(kp.k)) setStatus(kp.k); else setStatus('todos');
                  }}>
            <div className="kit-mlabel">{kp.label}</div>
            <div className={'kit-kpi ' + (kp.tone || '')}>{fmt(kp.value)}</div>
          </button>
        ))}
      </div>
      )}

      {/* Propostas paradas. Fica ACIMA de tudo porque é a única coisa da tela
          onde tem gente esperando por uma pessoa, não por um número. */}
      {!simple && pendingCount > 0 && (
        <div className="kit-card pad warn" data-pending-notice
             style={{ marginTop: 16, display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 13.5, fontWeight: 600, color: 'var(--warn-deep)' }}>
            {pendingCount} {pendingCount === 1 ? 'proposta esperando' : 'propostas esperando'}
            {pendingAge ? ' · a mais antiga há ' + pendingAge : ''}
          </span>
          <a className="kit-btn sm primary" style={{ marginLeft: 'auto' }} href="#estoque-aprovacoes">Ver aprovações</a>
        </div>
      )}

      {ov.loading && !ov.data && (
        <div className="kit-card pad" style={{ marginTop: 18, color: 'var(--ink-dim)' }}>Carregando o estoque…</div>
      )}
      {ov.error && (
        <div className="kit-card pad bad" style={{ marginTop: 18 }}>
          Não deu pra carregar o estoque: {ov.error.message}. Tentando de novo em 20s.
        </div>
      )}

      {/* ══ MODO SIMPLES: a tela do mutirão ══════════════════════════
          Placar + busca numa linha, e UMA linha por produto com tudo que o
          Bruno pediu acima da dobra: o número da Veeqo (o alvo), as três
          contagens editáveis no lugar, o chip que diz se bate, a impressora
          da etiqueta e a balança. */}
      {simple && (
        <>
          <div className="wht-scorebar" data-scorebar>
            <SimpleSearch q={q} onQ={setQ} />
            <span className="kit-mlabel" data-scoreboard>
              {data.simple_progress
                ? fmt(data.simple_progress.products) + ' produtos · '
                  + fmt(data.simple_progress.matching) + ' batendo com a Veeqo · '
                  + fmt(data.simple_progress.bottles_counted) + ' garrafas contadas de '
                  + fmt(data.simple_progress.veeqo_bottles) + ' na Veeqo'
                : (ov.loading ? 'carregando o placar…' : fmt(rows.length) + ' produtos')}
            </span>
          </div>

          {/* dia 1 do mutirão: tudo zerado é o ponto de partida, não um erro */}
          {rows.length > 0 && rows.every((r) => !n(r.total)) && (
            <div className="kit-card pad" style={{ marginTop: 12, color: 'var(--ink-dim)' }} data-simple-empty>
              Conte e digite direto na linha o que está no local AGORA (não soma). O alvo de cada produto é o número da Veeqo{data && data.veeqo_checked_at ? ' · ' + veeqoAgeLabel(data) : ''}.
            </div>
          )}

          <div className="kit-card" style={{ marginTop: 12, padding: '8px 12px 4px', overflowX: 'auto', overflowY: 'auto', maxHeight: '72vh' }}>
            <table className="kit-table" data-table="simples">
              <thead style={{ position: 'sticky', top: 0, zIndex: 3, background: 'var(--card-bg, #fff)', boxShadow: '0 1px 0 var(--line, #d4e2f0)' }}>
                <tr>
                  <th>Produto</th>
                  <th className="num" title="O que a Veeqo mostra agora (SKU base). É o alvo da contagem.">Veeqo</th>
                  <th className="num">Prateleira</th>
                  <th className="num">Caixa</th>
                  <th className="num">A organizar</th>
                  <th>Confere</th>
                  <th colSpan={2} aria-label="Imprimir e pesar" />
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => {
                  const hb = homeBinOf(r);
                  const mb = mainBoxOf(r);
                  const needCode = !hb && !(r.bins || []).length;
                  return (
                    <tr key={r.product_id} data-row={r.product_id}>
                      <td style={{ minWidth: 240 }}>
                        <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                          <span style={{ fontFamily: 'var(--font-display)', fontSize: 16, color: 'var(--primary-deep)' }}>
                            {r.nickname || r.name}
                          </span>
                          <SkuChip row={r} writable={false}
                                   expanded={!!expanded[r.product_id]}
                                   onToggle={() => setExpanded((x) => ({ ...x, [r.product_id]: !x[r.product_id] }))} />
                        </div>
                        {(hb || mb) && (
                          <div style={{ display: 'flex', gap: 5, marginTop: 4, flexWrap: 'wrap' }}>
                            {hb && <span className="kit-chip neutral" style={{ fontFamily: 'var(--font-mono)' }}>{hb.bin_code}</span>}
                            {mb && <span className="kit-chip neutral" style={{ fontFamily: 'var(--font-mono)' }}>{mb.box_number}</span>}
                          </div>
                        )}
                      </td>
                      <td className="num sep"><b data-veeqo-cell={r.product_id}>{fmt(veeqoOf(r))}</b></td>
                      <td className="num">
                        <SimpleCell value={r.shelf_qty} row={r} scope="shelf" writable={writable}
                                    askBinCode={needCode} suggestedCode={needCode ? suggestedCode : ''}
                                    hint={needCode
                                      ? 'Primeira contagem: digite quantas tem e o código da prateleira nova'
                                      : 'Clique, digite a contagem da prateleira e dê Enter'}
                                    onCommit={simpleCommit} />
                      </td>
                      <td className="num">
                        <SimpleCell value={r.box_qty} row={r} scope="box" writable={writable}
                                    hint={mb
                                      ? 'Clique, digite a contagem da caixa e dê Enter'
                                      : 'Primeira contagem: a caixa é criada sozinha com o próximo número BX'}
                                    onCommit={simpleCommit} />
                      </td>
                      <td className="num">
                        <SimpleCell value={r.unplaced_qty} row={r} scope="unplaced" writable={writable}
                                    hint="Clique, digite quantas estão soltas e dê Enter"
                                    onCommit={simpleCommit} />
                      </td>
                      <td><CompareChip row={r} /></td>
                      <td style={{ width: 34 }}>
                        <button className="kit-btn xs sec wht-rowbtn" data-act="print-row" data-print={r.product_id}
                                disabled={!hb && !mb}
                                title={hb || mb
                                  ? 'Imprimir as etiquetas da prateleira e da caixa deste produto'
                                  : 'Sem local ainda: salve uma contagem primeiro'}
                                onClick={() => printRow(r)}>🖨</button>
                      </td>
                      <td style={{ width: 34 }}>
                        {writable && (
                          <button className="kit-btn xs sec wht-rowbtn" data-act="pesar-row" data-pesar={r.product_id}
                                  title="Pesar a caixa pra contar sem abrir"
                                  onClick={() => setWeigh(r)}>⚖</button>
                        )}
                      </td>
                    </tr>
                  );
                })}
                {!rows.length && !ov.loading && (
                  <tr><td colSpan={8} style={{ color: 'var(--ink-faint)', padding: 20 }}>
                    Nenhum produto com essa busca. Apague e tente de novo.
                  </td></tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* Precisa de atenção hoje: os mais graves primeiro; no dia 1 (tudo zerado) seriam 190+ linhas, então mostra 8 e um botão pra abrir o resto */}
      {!simple && (data.attention || []).length > 0 && (
        <div className="kit-card pad" style={{ marginTop: 16 }} data-attention>
          <div className="kit-mlabel" style={{ marginBottom: 6, display: 'flex', alignItems: 'center', gap: 8 }}>
            <span>Precisa de atenção hoje</span>
            <span className="kit-chip neutral">{(data.attention || []).length}</span>
            {(data.attention || []).length > ATTN_LIMIT && (
              <button className="kit-btn xs sec" style={{ marginLeft: 'auto' }} onClick={() => setAttnAll((v) => !v)}>
                {attnAll ? 'mostrar menos' : 'ver todos (' + (data.attention || []).length + ')'}
              </button>
            )}
          </div>
          {(attnAll ? (data.attention || []) : (data.attention || []).slice(0, ATTN_LIMIT)).map((a, i) => {
            const row = rows.find((r) => r.product_id === a.product_id);
            return (
              <div key={i} className="kit-dotted-row">
                <span className={'kit-chip ' + (ATTENTION_TONE[a.kind] || 'neutral')}>{ATTENTION_LABEL[a.kind] || a.kind}</span>
                <b style={{ fontSize: 13.5 }}>{a.product}</b>
                <span style={{ flex: 1, color: 'var(--ink-dim)', fontSize: 12.5 }}>{a.text}</span>
                {a.action && a.action.type === 'aprovar' && writable && (
                  <button className="kit-btn xs" onClick={() => approve(a.action.request_id)}>Aprovar</button>
                )}
                {a.action && a.action.type === 'repor' && writable && row && (
                  <button className="kit-btn xs sec" onClick={() => openAction('mover', row)}>Repor</button>
                )}
                {a.action && a.action.type === 'organizar' && writable && row && (
                  <button className="kit-btn xs sec" onClick={() => openAction('organizar', row)}>Organizar</button>
                )}
                {a.action && a.action.type === 'entrada' && writable && row && (
                  <button className="kit-btn xs sec" onClick={() => openAction('receber', row)}>Receber</button>
                )}
                {a.action && a.action.type === 'ver' && row && (
                  <button className="kit-btn xs sec" onClick={() => setPanel(row)}>Ver</button>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* estado vazio do dia 1 */}
      {!simple && empty && (
        <div className="kit-card pad" style={{ marginTop: 16 }} data-empty>
          <div className="kit-h2">Nenhuma prateleira ou caixa cadastrada ainda</div>
          <p className="kit-sub" style={{ marginTop: 6 }}>
            Comece cadastrando as prateleiras e as caixas em Locais. Sem elas a picklist não sabe pra onde mandar o operador,
            e o hub do operador não deixa guardar nem contar nada.
          </p>
          <p className="kit-sub" style={{ marginTop: 4 }}>
            Depois traga os números: Importar da Veeqo puxa o total de cada produto, ou faça a primeira Entrada na mão.
          </p>
          <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap' }}>
            <a className="kit-btn primary" href="#estoque-locais">1. Cadastrar locais</a>
            {writable && <button className="kit-btn sec" onClick={() => setImportOpen({ only: null })}>2. Importar da Veeqo</button>}
            {writable && <button className="kit-btn sec" onClick={() => rows[0] && openAction('entrada', rows[0])}>ou fazer uma Entrada</button>}
          </div>
        </div>
      )}

      {/* filtro: busca com debounce, chips rápidos e a vista salva na conta */}
      {!simple && (
      <FilterBar
        q={q} onQ={setQ}
        chips={chips}
        onChip={(k) => setChips((c) => ({ ...c, [k]: !c[k] }))}
        onlyQty={onlyQty} onOnlyQty={setOnlyQty}
        shown={filtered.length} total={totalCount}
        sortLabel={(SORT_LABEL[sort.col] || sort.col) + ' ' + (sort.dir === 'asc' ? '↑' : '↓')}
        onClear={() => { setQ(''); setChips({}); setOnlyQty(false); setStatus('todos'); setArea('todas'); }}
        viewStatus={viewMeta.account ? 'vista salva na sua conta' : 'vista só neste navegador'}
        dirty={viewDirty}
        onSaveView={() => { setView(currentView); ack('Vista salva. Ela abre assim na próxima vez.'); }}
        onResetView={() => {
          setQ(''); setChips({}); setOnlyQty(false); setStatus('todos'); setArea('todas');
          setSort({ col: 'available', dir: 'asc' });
          setView(null);
        }}
      />
      )}

      {/* filtros de segunda linha: pouco usados, mas ninguém os perdeu */}
      {!simple && (
      <div style={{ display: 'flex', gap: 10, marginTop: 8, flexWrap: 'wrap', alignItems: 'center' }}>
        <select className="kit-input" value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="todos">Status: todos</option>
          {statuses.map((s) => <option key={s} value={s}>{statusLabel(s)}</option>)}
        </select>
        <select className="kit-input" value={area} onChange={(e) => setArea(e.target.value)}>
          <option value="todas">Área: todas</option>
          {areas.map((a) => <option key={a} value={a}>{a}</option>)}
        </select>
        <label style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12.5, color: 'var(--ink-dim)' }}>
          <input type="checkbox" checked={onlyToday} onChange={(e) => setOnlyToday(e.target.checked)} /> só com pedido hoje
        </label>
      </div>
      )}

      {/* linhas marcadas: a barra só existe quando há o que juntar */}
      {!simple && selectedIds.length > 0 && (
        <div className="wht-selbar" data-selbar>
          <b>{selectedIds.length} {selectedIds.length === 1 ? 'linha marcada' : 'linhas marcadas'}</b>
          <span>Se forem a mesma garrafa em SKUs diferentes, junte numa linha só.</span>
          <span className="wht-spacer" style={{ flex: 1 }} />
          {writable && selectedIds.length >= 2 && (
            <button className="kit-btn sm primary" data-act="juntar-selecionados"
                    onClick={() => setMergeOpen(true)}>Juntar selecionados</button>
          )}
          <button className="kit-btn sm sec" data-act="limpar-selecao"
                  onClick={() => setSelected({})}>Limpar</button>
        </div>
      )}

      {/* tabela · cabeçalho GRUDADO: a lista tem ~190 produtos, e sem isso quem
          rola perde de vista qual coluna é qual e lê o número errado. */}
      {!simple && (
      <div className="kit-card" style={{ marginTop: 12, padding: '8px 12px 4px', overflowX: 'auto', overflowY: 'auto', maxHeight: '68vh' }}>
        <table className="kit-table" data-table="produtos">
          <thead data-sticky style={{ position: 'sticky', top: 0, zIndex: 3, background: 'var(--card-bg, #fff)', boxShadow: '0 1px 0 var(--line, #d4e2f0)' }}>
            {/* TODA coluna numérica ordena, e a ordem é pedida ao servidor:
                "de maior pra menor" tem que valer pros 190 produtos, não só
                pra página que já está na tela. */}
            <tr>
              {writable && <th className="wht-selcol" />}
              <th className="sortable" data-sort="name" onClick={() => toggleSort('name')}
                  title="Ordenar por nome do produto">
                Produto{sort.col === 'name' ? (sort.dir === 'asc' ? ' ↑' : ' ↓') : ''}
              </th>
              <SortableTh col="total"     label="Total"       sort={sort} onSort={toggleSort} />
              <SortableTh col="shelf"     label="Prateleira"  sort={sort} onSort={toggleSort} />
              <SortableTh col="box"       label="Caixa"       sort={sort} onSort={toggleSort} />
              <SortableTh col="unplaced"  label="A organizar" sort={sort} onSort={toggleSort} />
              <SortableTh col="reserved"  label="Reservado"   sort={sort} onSort={toggleSort} />
              <SortableTh col="pending"   label="Pendente"    sort={sort} onSort={toggleSort} />
              <SortableTh col="available" label="Disponível"  sort={sort} onSort={toggleSort} />
              {/* Quantos dias o disponível ainda dura no ritmo de venda das
                  últimas semanas. É a coluna que diz o que produzir primeiro. */}
              <SortableTh col="days" label="Dias de estoque" sort={sort} onSort={toggleSort}
                          title="Disponível dividido pela média de venda por dia dos últimos 7 dias" />
              <SortableTh col="separated" label="Separadas"   sort={sort} onSort={toggleSort} />
              <SortableTh col="veeqo"     label="Veeqo"       sort={sort} onSort={toggleSort} className="sep" />
              <th>Status</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {filtered.map((r) => {
              const pend = n(r.pending_in) - n(r.pending_out);
              /* Prateleira e Caixa só viram input com UM local. Com duas
                 prateleiras, "prateleira = 40" não diz em qual, e chutar
                 mexeria no lugar errado: aí a célula fica de leitura e o
                 caminho é Mover, que pergunta de onde e pra onde. */
              const oneBin = (r.bins || []).length === 1;
              const oneBox = (r.boxes || []).length === 1;
              const manyLoc = (r.bins || []).length > 1 || (r.boxes || []).length > 1;
              return (
                <tr key={r.product_id}
                    className={'clickable' + (selected[r.product_id] ? ' wht-selected' : '')}
                    data-row={r.product_id}
                    onClick={() => setPanel(r)}>
                  {writable && (
                    <td className="wht-selcol" onClick={(e) => e.stopPropagation()}>
                      <input type="checkbox" data-select={r.product_id}
                             checked={!!selected[r.product_id]}
                             title="Marcar pra juntar com outra linha da mesma garrafa"
                             onChange={() => setSelected((s) => ({ ...s, [r.product_id]: !s[r.product_id] }))} />
                    </td>
                  )}
                  <td style={{ minWidth: 300 }}>
                    <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                      <span style={{ fontFamily: 'var(--font-display)', fontSize: 16, color: 'var(--primary-deep)' }}>
                        <InlineText value={r.nickname} placeholder={r.name} writable={writable}
                                    tabIndexKey={r.product_id + ':nickname'}
                                    hint="Clique pra editar o apelido"
                                    onCommit={(v) => inlineNickname(r, v)} />
                      </span>
                      <span style={{ color: 'var(--ink-faint)', fontSize: 12 }}>{r.name}</span>
                    </div>
                    {/* UMA linha por produto: os SKUs ficam dobrados no chip */}
                    <div style={{ display: 'flex', gap: 5, marginTop: 4, flexWrap: 'wrap', alignItems: 'center' }}>
                      <SkuChip row={r} writable={writable} onUnmerge={onUnmerge}
                               expanded={!!expanded[r.product_id]}
                               onToggle={() => setExpanded((x) => ({ ...x, [r.product_id]: !x[r.product_id] }))} />
                      {locChips(r).map((c) => (
                        <span key={c.k} className="kit-chip neutral" style={{ fontFamily: 'var(--font-mono)' }}>{c.t}</span>
                      ))}
                      {!locChips(r).length && <span className="kit-chip warn">sem local</span>}
                    </div>
                  </td>
                  <td className="num"><b>{fmt(r.total)}</b></td>
                  <td className="num">
                    <InlineNumber value={r.shelf_qty} row={r} field="shelf" writable={writable}
                                  disabled={manyLoc && !oneBin}
                                  needsReason tabIndexKey={r.product_id + ':shelf'}
                                  hint={oneBin ? 'Clique, digite a contagem da prateleira e dê Enter'
                                               : 'Sem prateleira única: use Mover'}
                                  reasonPlaceholder="motivo (ex: contagem da prateleira)"
                                  onCommit={inlineEdit} />
                  </td>
                  <td className="num">
                    <InlineNumber value={r.box_qty} row={r} field="box" writable={writable}
                                  disabled={manyLoc && !oneBox}
                                  needsReason tabIndexKey={r.product_id + ':box'}
                                  hint={oneBox ? 'Clique, digite a contagem da caixa e dê Enter'
                                               : 'Sem caixa única: use Mover'}
                                  reasonPlaceholder="motivo (ex: contagem da caixa)"
                                  onCommit={inlineEdit} />
                  </td>
                  <td className="num" style={n(r.unplaced_qty) ? { color: 'var(--warn-deep)', fontWeight: 600 } : undefined}>
                    <InlineNumber value={r.unplaced_qty} row={r} field="unplaced" writable={writable}
                                  needsReason tabIndexKey={r.product_id + ':unplaced'}
                                  hint="Clique, digite quantas estão soltas e dê Enter"
                                  reasonPlaceholder="motivo (ex: chegou lote novo)"
                                  onCommit={inlineEdit} />
                  </td>
                  <td className="num">{fmt(r.reserved)}</td>
                  <td className="num" style={pend ? { color: pend < 0 ? 'var(--bad-deep)' : 'var(--ok-deep)', fontWeight: 600 } : undefined}>
                    {pend ? (pend > 0 ? '+' + pend : String(pend)) : '0'}
                  </td>
                  <td className="num" style={n(r.available) < 0 ? { color: 'var(--bad-deep)', fontWeight: 700 } : undefined}>{fmt(r.available)}</td>
                  <td className="num" data-cell="days">
                    {r.days_of_stock == null
                      ? <span style={{ color: 'var(--ink-faint)' }}>—</span>
                      : (() => {
                          const tone = dosTone(r.days_of_stock);
                          return (
                            <span style={tone === 'bad' ? { color: 'var(--bad-deep)', fontWeight: 700 }
                                       : tone === 'warn' ? { color: 'var(--warn-deep)', fontWeight: 600 }
                                       : undefined}>
                              {fmtDays(r.days_of_stock)}
                            </span>
                          );
                        })()}
                  </td>
                  <td className="num">{fmt(r.separated)}</td>
                  <td className="num sep">
                    {r.veeqo ? (
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, justifyContent: 'flex-end' }}>
                        {fmt(r.veeqo.physical)}
                        {r.veeqo_match === 'ok' && <span className="kit-chip ok">✓</span>}
                        {r.veeqo_match === 'drift' && (
                          <span className="kit-chip bad">Δ {n(r.veeqo.physical) - n(r.total) > 0 ? '+' : ''}{n(r.veeqo.physical) - n(r.total)}</span>
                        )}
                        {r.veeqo_match === 'unknown' && <span className="kit-chip neutral">?</span>}
                      </span>
                    ) : <span className="kit-chip neutral">?</span>}
                  </td>
                  <td>
                    <span style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      {(r.status || []).map((s) => <span key={s} className={'kit-chip ' + statusTone(s)}>{statusLabel(s)}</span>)}
                    </span>
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    <RowMenu row={r} writable={writable} onAction={openAction} />
                  </td>
                </tr>
              );
            })}
            {!filtered.length && !ov.loading && (
              <tr><td colSpan={writable ? 14 : 13} style={{ color: 'var(--ink-faint)', padding: 20 }}>
                Nenhum produto com esses filtros. Tire um chip ou limpe a busca.
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
      )}

      {/* Paginação por botão, não por rolagem infinita: quem está conferindo
          estoque precisa saber onde parou, e uma lista que cresce sozinha
          embaixo do dedo tira esse chão. */}
      {!simple && hasMore && (
        <div className="wht-more" data-more>
          <span className="kit-mlabel">
            mostrando {fmt(filtered.length)} de {fmt(totalCount)}
          </span>
          <button className="kit-btn sm sec" data-act="carregar-mais"
                  onClick={() => setPageSize((s) => s + PAGE)}>Carregar mais</button>
        </div>
      )}

      {data.veeqo_checked_at && (
        <div className="kit-mlabel" style={{ marginTop: 10 }} data-veeqo-source={data.veeqo_source || 'live'}>
          {veeqoAgeLabel(data)} · a coluna Veeqo é comparação, nunca entra na soma
        </div>
      )}

      {/* popover da balança (modo simples): pesa, calcula e preenche a Caixa */}
      {weigh && (() => {
        const wrow = rowsPatch[weigh.product_id]
          || rows.find((r) => r.product_id === weigh.product_id) || weigh;
        return (
          <WeighPopover
            row={wrow}
            weight={weightOf(weigh.product_id)}
            tares={(ws.data && ws.data.tares) || []}
            onCompute={(b) => wh.computeCount(b).then((j) => (j && j.data) || j)}
            onCalibrate={(b) => wh.setProductWeight(weigh.product_id, b).then(() => { ws.refresh(); })}
            onUse={async (qty) => {
              try { await simpleCommit({ row: wrow, scope: 'box', qty }); setWeigh(null); }
              catch (e) { /* o toast já explicou; o popover fica aberto */ }
            }}
            onClose={() => setWeigh(null)}
          />
        );
      })()}

      {modal && (
        <ActionModal
          action={modal.action} row={modal.row}
          onClose={() => setModal(null)}
          onError={(m) => ackErr(m)}
          onDone={(product, msg) => { setModal(null); if (product) onRowUpdate(product); ack(msg); ov.refresh(); }}
        />
      )}

      {importOpen && (
        <ImportVeeqoModal
          rows={rows} only={importOpen.only}
          onClose={() => setImportOpen(null)}
          onError={(m) => ackErr(m)}
          onDone={(msg) => { setImportOpen(null); ack(msg); ov.refresh(); }}
        />
      )}

      {mergeOpen && (
        <MergePanel
          writable={writable}
          adhoc={selectedIds}
          allRows={rows}
          onClose={() => setMergeOpen(false)}
          onError={ackErr}
          onDone={onMergeDone}
        />
      )}

      {driftOpen && (
        <DriftPanel
          rows={rows} writable={writable}
          onClose={() => setDriftOpen(false)}
          onOpen={(row) => { setDriftOpen(false); setPanel(row); }}
          onImport={(row) => { setDriftOpen(false); setImportOpen({ only: row }); }}
        />
      )}

      {panel && (
        <ProductPanel
          row={rowsPatch[panel.product_id] || panel}
          allRows={rows}
          writable={writable}
          ack={ack}
          onRowUpdate={onRowUpdate}
          onAction={(a, p) => openAction(a, rowsPatch[p.product_id] || p)}
          onClose={() => setPanel(null)}
        />
      )}

      {toast && (
        <div className={'kit-toast ' + (toast.bad ? 'bad' : '')}>
          {toast.msg}
          {toast.action && (
            <button className="kit-btn xs" data-act="toast-acao" style={{ marginLeft: 10 }}
                    onClick={() => { setToast(null); toast.action.run(); }}>
              {toast.action.label}
            </button>
          )}
        </div>
      )}
    </div>
  );
}
