import React from 'react';
import { createPortal } from 'react-dom';

/* ═══════════════════════════════════════════════════════════════════
   WIDGET GRID — grade arrastável e redimensionável da página Hoje.

   Bruno 08-19: "os widgets deveriam ser draggable, que a gente pudesse mudar
   tamanho, lugar, ajustar em qualquer lugar dessa área".

   Escrita à mão de propósito: o npm desta máquina está quebrado, então nada de
   react-grid-layout. São ~300 linhas de pointer events + uma função de
   compactação; o comportamento que importa (arrastar pelo título, puxar o
   canto, nada sobrepõe, o estado sobrevive ao F5) cabe nisso.

   MODELO
     - 12 colunas. Altura da linha = ROW_H, mais GAP entre células.
     - Cada widget = { id, x, y, w, h, on }. x/y/w/h em unidades de grade.
     - Layout persistido em localStorage 'hf-hoje-layout-v2'.
     - Nada sobrepõe: depois de cada mexida o layout é COMPACTADO pra cima
       (cada widget sobe até encostar em outro ou no topo), que é o mesmo
       comportamento que as pessoas já conhecem de dashboards.

   TABLET (< 900px): uma coluna só, drag/resize desligados. Puxar bloco de
   56px com o dedo num tablet só gera layout quebrado sem querer; quem precisa
   reorganizar faz no desktop, e o popover de Widgets tem subir/descer pra
   quem usa teclado ou toque.
   ═══════════════════════════════════════════════════════════════════ */

export const COLS = 12;
export const ROW_H = 56;
export const GAP = 14;
export const NARROW_PX = 900;

/* ── util de layout ─────────────────────────────────────────────── */

const clone = (l) => l.map((w) => ({ ...w }));
const overlaps = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

/** Sobe cada widget até encostar. Determinístico: ordena por y, depois x. */
export function compact(layout) {
  const out = clone(layout).sort((a, b) => (a.y - b.y) || (a.x - b.x));
  const placed = [];
  for (const w of out) {
    let y = 0;
    // desce até achar a primeira faixa livre a partir do topo
    for (;;) {
      const probe = { ...w, y };
      const hit = placed.find((p) => overlaps(probe, p));
      if (!hit) break;
      y = hit.y + hit.h;
    }
    w.y = y;
    placed.push(w);
  }
  return out;
}

/** Empurra pra baixo quem colide com `moving`, depois compacta. */
export function resolve(layout, moving) {
  const out = clone(layout).map((w) => (w.id === moving.id ? { ...moving } : w));
  const me = out.find((w) => w.id === moving.id);
  // quem colide com o widget movido desce pro fim dele
  let guard = 0;
  for (;;) {
    const hit = out.find((w) => w.id !== me.id && w.on && me.on && overlaps(w, me));
    if (!hit || guard++ > 200) break;
    hit.y = me.y + me.h;
  }
  // compacta só os ligados; os desligados guardam a posição pra quando voltarem
  const on = out.filter((w) => w.on);
  const off = out.filter((w) => !w.on);
  const packed = compact(on);
  const byId = new Map(packed.map((w) => [w.id, w]));
  return out.map((w) => byId.get(w.id) || off.find((o) => o.id === w.id) || w);
}

const clampW = (w, min, max) => Math.max(min, Math.min(max, w));

/* ── o componente ───────────────────────────────────────────────── */

/**
 * @param layout   [{id,x,y,w,h,on}]
 * @param onLayout (next) => void        chamado no fim de cada drag/resize
 * @param defs     { [id]: { label, minW, minH } }
 * @param children (id) => ReactNode     conteúdo de cada widget
 * @param narrow   bool                  força coluna única (tablet)
 */
export function WidgetGrid({ layout, onLayout, defs, renderWidget, narrow: narrowProp, editRequest }) {
  const ref = React.useRef(null);
  const [colPx, setColPx] = React.useState(100);
  const [autoNarrow, setAutoNarrow] = React.useState(false);
  // drag = { id, mode:'move'|'resize', startX, startY, orig, ghost }
  const [drag, setDrag] = React.useState(null);
  // layout mostrado enquanto arrasta (preview ao vivo); null = usa o de fora
  const [preview, setPreview] = React.useState(null);
  // 09-11: popover de opções (zoom, ajuste ao espaço, presets) aberto pra qual widget
  const [opts, setOpts] = React.useState(null);
  // MODO DE EDIÇÃO (Bruno 09-11: "que nem a tela inicial do iPhone"): fora dele, nada se move
  // nem redimensiona por acidente. Entra com duplo clique num widget ou pelo botão Widgets →
  // Ajustar; os blocos balançam; sai com Enter, Esc ou o botão OK no topo.
  const [edit, setEdit] = React.useState(false);
  React.useEffect(() => { if (editRequest) setEdit(true); }, [editRequest]);
  React.useEffect(() => {
    if (!edit) return undefined;
    const onKey = (e) => { if (e.key === 'Enter' || e.key === 'Escape') { e.preventDefault(); setEdit(false); } };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [edit]);

  const narrow = narrowProp != null ? narrowProp : autoNarrow;

  /* Largura da coluna + modo estreito, medidos do container REAL.
     Os filhos são absolutos, então o container não tem largura própria: quem
     manda é o pai. Medir cedo demais (antes da sidebar assentar) dava coluna
     larga e o último widget saía pela direita, então a medida também roda no
     ResizeObserver do PAI e num rAF depois da montagem. */
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const measure = () => {
      /* Mede o AVÔ (o .main-inner), não o próprio container: os filhos são
         absolutos, então .wg-root não impõe largura nenhuma e, num pai que
         rola no eixo x, ele acaba lendo a largura do CONTEÚDO, não a da área.
         Isso inflava a coluna e o último widget saía pela direita. */
      const host = (el.parentElement && el.parentElement.parentElement) || el.parentElement || el;
      const cs = window.getComputedStyle(host);
      const pad = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
      const avail = Math.max(0, (host.clientWidth || 0) - pad);
      const wpx = avail > 1 ? avail : (el.clientWidth || 1);
      if (wpx <= 1) return;
      setAutoNarrow(wpx < NARROW_PX);
      setColPx(Math.max(1, (wpx - GAP * (COLS - 1)) / COLS));
    };
    measure();
    const raf = requestAnimationFrame(measure);
    const t = setTimeout(measure, 250);
    let ro = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(measure);
      ro.observe(el);
      if (el.parentElement) ro.observe(el.parentElement);
      if (el.parentElement && el.parentElement.parentElement) ro.observe(el.parentElement.parentElement);
    }
    window.addEventListener('resize', measure);
    return () => {
      cancelAnimationFrame(raf); clearTimeout(t);
      if (ro) ro.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);

  const live = preview || layout;
  const on = live.filter((w) => w.on);

  /* ── pointer: arrastar (pela alça do cabeçalho) e redimensionar ── */
  const startDrag = (e, w, mode) => {
    if (narrow) return;                       // tablet: sem drag
    if (!edit) return;                        // só no modo de edição (Bruno 09-11)
    if (e.button != null && e.button !== 0) return;
    e.preventDefault();
    e.stopPropagation();
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (_) { /* jsdom */ }
    setDrag({ id: w.id, mode, startX: e.clientX, startY: e.clientY, orig: { ...w }, pointerId: e.pointerId });
    setPreview(clone(live));
  };

  React.useEffect(() => {
    if (!drag) return undefined;
    const def = (defs && defs[drag.id]) || {};
    const minW = def.minW || 1;
    const minH = def.minH || 1;

    const onMove = (ev) => {
      const dx = Math.round((ev.clientX - drag.startX) / (colPx + GAP));
      const dy = Math.round((ev.clientY - drag.startY) / (ROW_H + GAP));
      const o = drag.orig;
      let next;
      if (drag.mode === 'move') {
        next = { ...o, x: clampW(o.x + dx, 0, COLS - o.w), y: Math.max(0, o.y + dy) };
      } else {
        next = { ...o, w: clampW(o.w + dx, minW, COLS - o.x), h: Math.max(minH, o.h + dy) };
      }
      setPreview((prev) => resolve(prev || live, next));
    };
    const onUp = () => {
      setPreview((prev) => {
        if (prev && onLayout) onLayout(prev);
        return null;
      });
      setDrag(null);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
    };
  // live/onLayout mudam a cada render; o drag em curso só precisa do snapshot.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [drag, colPx, defs]);

  // altura total (pra o container reservar espaço enquanto arrasta)
  const rows = on.reduce((m, w) => Math.max(m, w.y + w.h), 0);
  const px = (n) => n * (ROW_H + GAP) - GAP;

  if (narrow) {
    // coluna única, na ordem de leitura do layout (y, depois x)
    const ordered = on.slice().sort((a, b) => (a.y - b.y) || (a.x - b.x));
    return (
      <div className="wg-root wg-narrow" ref={ref} data-widget-grid data-narrow="1">
        {ordered.map((w) => (
          <section key={w.id} className="wg-item" data-widget={w.id}>
            {renderWidget(w.id, { narrow: true })}
          </section>
        ))}
      </div>
    );
  }

  return (
    <div className={`wg-root ${edit ? 'wg-edit' : ''}`} ref={ref} data-widget-grid data-edit={edit ? '1' : '0'}
         style={{ height: rows > 0 ? px(rows) : 0 }}>
      {edit && createPortal(
        <div className="wg-editbar" data-widget-editbar>
          <span>Ajustando os widgets: arraste pelo título pra mover, puxe o canto pra mudar o tamanho.</span>
          <button className="ok" onClick={() => setEdit(false)}>OK</button>
          <small>Enter ou Esc também saem</small>
        </div>, document.body)}
      {/* sombra do lugar onde o bloco vai cair */}
      {drag && (() => {
        const g = on.find((w) => w.id === drag.id);
        if (!g) return null;
        return (
          <div className="wg-ghost" data-widget-ghost aria-hidden="true"
               style={{
                 transform: `translate(${g.x * (colPx + GAP)}px, ${g.y * (ROW_H + GAP)}px)`,
                 width: g.w * colPx + (g.w - 1) * GAP,
                 height: px(g.h),
               }}/>
        );
      })()}

      {on.map((w) => {
        const def = (defs && defs[w.id]) || {};
        const dragging = drag && drag.id === w.id;
        // 09-11 (Bruno): texto se ajusta ao espaço. fit = zoom proporcional ao tamanho padrão do
        // widget (menor widget → conteúdo menor, sem cortar); z = zoom manual. Presets por widget.
        const baseW = (def.w || w.w) * colPx, baseH = (def.h || w.h) * ROW_H;
        const fitZ = w.fit ? Math.max(0.4, Math.min(1.3, Math.min((w.w * colPx) / baseW, (w.h * ROW_H) / baseH))) : null;
        const zoom = w.z != null ? w.z : (fitZ != null ? fitZ : 1);
        // escala REAL (transform) com compensação de largura/altura: o conteúdo ocupa o espaço todo
        // e o texto encolhe/cresce junto; `zoom` CSS não existe em todo navegador.
        const bodyStyle = zoom !== 1 ? { transform: `scale(${zoom})`, transformOrigin: '0 0', width: `${(100 / zoom).toFixed(2)}%`, height: `${(100 / zoom).toFixed(2)}%` } : undefined;
        return (
          <section key={w.id}
                   className={`wg-item ${dragging ? 'wg-dragging' : ''} ${edit ? 'wg-editing' : ''}`}
                   data-widget={w.id}
                   onDoubleClick={(e) => { if (!edit && !e.target.closest('input, button, select, textarea, a, video, canvas')) setEdit(true); }}
                   data-x={w.x} data-y={w.y} data-w={w.w} data-h={w.h}
                   style={{
                     transform: `translate(${w.x * (colPx + GAP)}px, ${w.y * (ROW_H + GAP)}px)`,
                     '--tx': `${w.x * (colPx + GAP)}px`, '--ty': `${w.y * (ROW_H + GAP)}px`,   // o balanço do modo de edição precisa manter a posição
                     width: w.w * colPx + (w.w - 1) * GAP,
                     height: px(w.h),
                   }}>
            {/* alça: arrasta pelo título, como o Bruno pediu */}
            <div className="wg-handle" data-widget-handle={w.id}
                 title={edit ? `Arraste pra mover "${def.label || w.id}"` : 'Duplo clique pra ajustar os widgets (mover e redimensionar)'}
                 onPointerDown={(e) => startDrag(e, w, 'move')}>
              <span className="wg-grip" aria-hidden="true">⋮⋮</span>
              <span className="wg-title kit-mlabel">{def.label || w.id}</span>
              <button className="wg-gear" data-widget-gear={w.id} title="Tamanho, texto e presets deste widget"
                      onPointerDown={(e) => e.stopPropagation()} onClick={(e) => { e.stopPropagation(); setOpts(opts && opts.id === w.id ? null : { id: w.id, anchor: { x: e.clientX, y: e.clientY } }); }}>⚙</button>
            </div>
            <div className="wg-body-clip"><div className="wg-body" style={bodyStyle} data-zoom={zoom.toFixed(2)}>{renderWidget(w.id, { narrow: false })}</div></div>
            {opts && opts.id === w.id && (
              <WidgetOptions w={w} def={def} zoom={zoom} anchor={opts.anchor} onClose={() => setOpts(null)}
                             onChange={(patch) => onLayout(layout.map((x) => (x.id === w.id ? { ...x, ...patch } : x)))}
                             onResetAll={() => onLayout(layout.map((x) => ({ ...x, z: null, fit: false })))}/>
            )}
            {/* canto: muda o tamanho */}
            {edit && <div className="wg-resize" data-widget-resize={w.id}
                 title="Puxe pra mudar o tamanho"
                 onPointerDown={(e) => startDrag(e, w, 'resize')}/>}
          </section>
        );
      })}
    </div>
  );
}

/* WidgetOptions (Bruno 09-11): "deixar eu ajustar o tamanho e o texto auto fit o espaço que eu
   escolher... o widget deveria ter seu próprio preset lá na opção do widget".
   Posição FIXA na janela (nunca fica cortado dentro do widget), tamanho livre W×H. */
function WidgetOptions({ w, def, zoom, anchor, onClose, onChange, onResetAll }) {
  const [name, setName] = React.useState('');
  const presets = w.presets || {};
  const names = Object.keys(presets);
  const minW = def.minW || 1, minH = def.minH || 1;
  React.useEffect(() => {
    const onDoc = (e) => { if (!e.target.closest('.wg-opts, .wg-gear')) onClose(); };
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('mousedown', onDoc); document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDoc); document.removeEventListener('keydown', onKey); };
  }, [onClose]);
  const vw = window.innerWidth || 1200, vh = window.innerHeight || 800;
  const left = Math.max(8, Math.min(vw - 328, (anchor ? anchor.x : vw / 2) - 300));
  const top = Math.max(8, Math.min(vh - 460, (anchor ? anchor.y : 80) + 10));
  const setSize = (nw, nh) => onChange({ w: Math.max(minW, Math.min(COLS, nw)), h: Math.max(minH, Math.min(30, nh)) });
  const Stepper = ({ label, value, min, max, onSet }) => (
    <div className="wg-step"><span>{label}</span><button onClick={() => onSet(Math.max(min, value - 1))}>−</button><b>{value}</b><button onClick={() => onSet(Math.min(max, value + 1))}>+</button></div>
  );
  // PORTAL (Bruno 09-11: "clica no gear e nada acontece"): o .wg-item tem transform, e position:fixed
  // dentro de um elemento com transform vira relativo a ele → o popover caía fora do widget, cortado
  // pelo overflow:hidden. No body, fixed é fixed de verdade.
  return createPortal(
    <div className="wg-opts" style={{ position: 'fixed', left, top }} onPointerDown={(e) => e.stopPropagation()}>
      <div className="wg-opts-h">{def.label || w.id} <small>{w.w} colunas × {w.h} linhas</small><button className="wg-x" onClick={onClose} title="Fechar">✕</button></div>
      <div className="wg-opts-h" style={{ marginTop: 6 }}>Tamanho (qualquer forma)</div>
      <div className="wg-opts-row"><Stepper label="Largura" value={w.w} min={minW} max={COLS} onSet={(v) => setSize(v, w.h)}/><Stepper label="Altura" value={w.h} min={minH} max={30} onSet={(v) => setSize(w.w, v)}/></div>
      <div className="wg-opts-row sizes"><span>Atalhos</span>
        {[[2, 2, 'P'], [3, 3, 'M'], [4, 3, 'Largo'], [6, 4, 'G'], [12, 5, 'Faixa']].map(([cw, ch, t]) => (<button key={t} className={w.w === cw && w.h === ch ? 'on' : ''} onClick={() => setSize(cw, ch)}>{t}</button>))}
      </div>
      <div className="wg-opts-h" style={{ marginTop: 8 }}>Texto</div>
      <label className="wg-opts-row"><input type="checkbox" checked={!!w.fit && w.z == null} onChange={(e) => onChange({ fit: e.target.checked, z: null })}/> Ajustar ao espaço automaticamente <small>(encolhe/cresce com o tamanho)</small></label>
      <div className="wg-opts-row"><span>Escala {Math.round(zoom * 100)}%</span>
        <input type="range" min="40" max="140" step="5" value={Math.round(zoom * 100)} onChange={(e) => onChange({ z: Number(e.target.value) / 100, fit: false })}/>
        <button className="lnk" onClick={() => onChange({ z: null, fit: false })}>100%</button>
      </div>
      <div className="wg-opts-h" style={{ marginTop: 8 }}>Presets deste widget</div>
      {names.length === 0 && <div className="wg-opts-hint">Nenhum ainda. Ajuste tamanho e texto, dê um nome e salve.</div>}
      {names.map((n) => (<div key={n} className="wg-opts-row preset"><span>{n} <small>{presets[n].w}×{presets[n].h} · {Math.round((presets[n].z || 1) * 100)}%{presets[n].fit ? ' · auto' : ''}</small></span>
        <button className="lnk" onClick={() => onChange({ w: presets[n].w, h: presets[n].h, z: presets[n].z != null ? presets[n].z : null, fit: !!presets[n].fit })}>aplicar</button>
        <button className="lnk" onClick={() => { const p = { ...presets }; delete p[n]; onChange({ presets: p }); }}>apagar</button></div>))}
      <div className="wg-opts-row"><input type="text" placeholder="nome do preset" value={name} onChange={(e) => setName(e.target.value)}/>
        <button className="lnk" disabled={!name.trim()} onClick={() => { onChange({ presets: { ...presets, [name.trim()]: { w: w.w, h: w.h, z: w.z, fit: !!w.fit } } }); setName(''); }}>salvar</button></div>
      <div className="wg-opts-row" style={{ justifyContent: 'space-between', marginTop: 6 }}>
        <button className="lnk" onClick={() => onChange({ w: def.w || w.w, h: def.h || w.h, z: null, fit: false })}>Este widget ao padrão</button>
        <button className="lnk" onClick={onResetAll}>Texto de todos em 100%</button>
      </div>
    </div>,
    document.body
  );
}

export default WidgetGrid;
